CREATE TABLE learning_settings(goal_id TEXT PRIMARY KEY REFERENCES goals(id), archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE capability_sets(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),content TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE knowledge_nodes(id TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL);
CREATE TABLE readiness_items(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),set_id TEXT NOT NULL REFERENCES capability_sets(id),title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('CORE','SUPPORTING')));
CREATE TABLE requirements(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),set_id TEXT NOT NULL REFERENCES capability_sets(id),readiness_id TEXT NOT NULL REFERENCES readiness_items(id),node_id TEXT NOT NULL REFERENCES knowledge_nodes(id),description TEXT NOT NULL);
CREATE TABLE material_contents(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES resources(id),scope TEXT NOT NULL,content TEXT NOT NULL,hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE material_analysis(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES resources(id),content_id TEXT REFERENCES material_contents(id),scope TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE roadmap_details(proposal_id TEXT PRIMARY KEY REFERENCES proposals(id),set_id TEXT NOT NULL REFERENCES capability_sets(id),structure TEXT NOT NULL);
CREATE TABLE session_details(session_id TEXT PRIMARY KEY REFERENCES sessions(id),phase TEXT NOT NULL,topic TEXT NOT NULL,requirements TEXT NOT NULL,resources TEXT NOT NULL,dependencies TEXT NOT NULL);
CREATE TABLE assessments(id TEXT PRIMARY KEY,conversation_id TEXT UNIQUE NOT NULL REFERENCES conversations(id),goal_id TEXT NOT NULL REFERENCES goals(id),session_id TEXT REFERENCES sessions(id),kind TEXT NOT NULL,mode TEXT NOT NULL,status TEXT NOT NULL,scope TEXT NOT NULL,requirement_ids TEXT NOT NULL,material_refs TEXT NOT NULL,parent_id TEXT REFERENCES assessments(id),gap_id TEXT,summary TEXT,created_at TEXT NOT NULL,ended_at TEXT);
CREATE TABLE assessment_rounds(id TEXT PRIMARY KEY,assessment_id TEXT NOT NULL REFERENCES assessments(id),question_message_id TEXT UNIQUE NOT NULL REFERENCES messages(id),answer_message_id TEXT UNIQUE REFERENCES messages(id),feedback TEXT,requirement_ids TEXT NOT NULL);
CREATE TABLE assessment_capabilities(assessment_id TEXT PRIMARY KEY REFERENCES assessments(id),set_id TEXT NOT NULL REFERENCES capability_sets(id));
CREATE TABLE evidence_requirements(evidence_id TEXT NOT NULL REFERENCES evidence(id),requirement_id TEXT NOT NULL REFERENCES requirements(id),relation TEXT NOT NULL CHECK(relation IN ('SUPPORTS','CONTRADICTS','INCONCLUSIVE')),PRIMARY KEY(evidence_id,requirement_id));
CREATE TABLE gaps(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),requirement_id TEXT NOT NULL REFERENCES requirements(id),description TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,evidence_id TEXT REFERENCES evidence(id),reopen_count INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE reviews(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),gap_id TEXT REFERENCES gaps(id),requirement_id TEXT NOT NULL REFERENCES requirements(id),due_date TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,assessment_id TEXT REFERENCES assessments(id));
CREATE TABLE readiness_judgments(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),set_id TEXT NOT NULL REFERENCES capability_sets(id),assessment_id TEXT NOT NULL REFERENCES assessments(id),judgments TEXT NOT NULL,completion_recommended INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE goal_snapshots(goal_id TEXT PRIMARY KEY REFERENCES goals(id),kind TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX idx_assessments_goal ON assessments(goal_id,created_at);
CREATE INDEX idx_rounds_assessment ON assessment_rounds(assessment_id);
CREATE INDEX idx_requirements_goal ON requirements(goal_id);
CREATE INDEX idx_reviews_date ON reviews(status,due_date);
